-- Catálogo de complementos con precios por nivel (14 nov 2026). Generado desde lib/pagina-viva.ts.
-- Nivel 1 Simple $0 · Nivel 2 Funcional $1,490 · Nivel 3 Pagos y comercio $3,490 · Nivel 4 Sistema a medida desde $6,990.
-- Producción creativa por pieza; agentes, marketing y operación mensuales.

on conflict (id) do update set
  tipo = excluded.tipo, nombre = excluded.nombre, resumen = excluded.resumen, precio_mxn = excluded.precio_mxn,
  cobro = excluded.cobro, automatico = excluded.automatico, incluye = excluded.incluye, orden = excluded.orden, activo = true;

-- Lo que ya no se vende así: el agente pasó a mensual y Página Viva cambió de precio.
update public.productos set activo = false
  where tipo = 'complemento' and id not in ('modulo-paginas', 'modulo-popup', 'modulo-barra-aviso', 'modulo-cuenta-regresiva', 'modulo-galeria', 'modulo-video-insertado', 'modulo-feed-instagram', 'modulo-resenas-google', 'modulo-botones-llegar', 'modulo-enlaces-bio', 'modulo-qr', 'modulo-formulario-extra', 'modulo-pdf-precios', 'modulo-messenger', 'modulo-citas', 'modulo-ingles', 'modulo-cotizador', 'modulo-catalogo', 'modulo-pedidos-whatsapp', 'modulo-menu-qr', 'modulo-blog', 'modulo-bolsa-trabajo', 'modulo-cupones', 'modulo-encuesta', 'modulo-newsletter', 'modulo-testimonios', 'modulo-sucursales', 'modulo-referidos', 'modulo-landing-campana', 'modulo-comparador', 'modulo-tienda', 'modulo-reservas', 'modulo-boletos', 'modulo-membresias', 'modulo-cursos', 'modulo-facturacion', 'modulo-envios', 'modulo-oxxo-spei', 'modulo-tarjetas-regalo', 'modulo-donaciones', 'modulo-pos', 'modulo-admin', 'modulo-inventario', 'modulo-area-clientes', 'modulo-marketplace', 'modulo-cotizaciones-flujo', 'modulo-integracion', 'modulo-app', 'modulo-reportes', 'modulo-marca', 'modulo-fotos', 'modulo-video', 'modulo-lanzamiento', 'modulo-manual-identidad', 'modulo-video-portada', 'modulo-textos', 'modulo-ilustraciones', 'modulo-recorrido-360', 'mensual-agente-web', 'mensual-agente-redes', 'mensual-agente-agenda', 'mensual-seguimiento', 'mensual-agente-voz', 'mensual-anuncios', 'mensual-seo', 'mensual-perfil-google', 'mensual-correos', 'mensual-redes', 'hospedaje', 'mensual-correo-dominio', 'mensual-respaldos');
update public.productos set precio_mxn = 7990 where id = 'pagina-viva';
